use adw::prelude::*;
use adw::{Application, ApplicationWindow, Toast, ToastOverlay};
use adw::gtk::{Button, ListBox, ToggleButton};
use adw::{OverlaySplitView, StatusPage, WindowTitle};
use gtk4::gio;

const APP_ID: &str = "in.tl2a.kopico-desktop";

// (title, icon) for each sidebar entry — drives the row-selected handler
const PAGES: [(&str, &str); 3] = [
    ("Home", "go-home-symbolic"),
    ("Documents", "folder-documents-symbolic"),
    ("Settings", "emblem-system-symbolic"),
];

fn main() -> gtk4::glib::ExitCode {
    // Register the compiled GResource (generated by build.rs via blueprint-compiler
    // + glib-compile-resources, then embedded with include_bytes!).
    let bytes = include_bytes!(env!("GRESOURCE_FILE"));
    let resource = gio::Resource::from_data(&gtk4::glib::Bytes::from_static(bytes))
        .expect("Failed to load gresource data");
    gio::resources_register(&resource);

    let app = Application::builder().application_id(APP_ID).build();
    app.connect_activate(build_ui);
    app.run()
}

fn build_ui(app: &Application) {
    // ── Load all widgets from the Blueprint-compiled UI resource ──────────────
    let builder = gtk4::Builder::from_resource("/in/tl2a/kopico-desktop/ui/window.ui");

    let window: ApplicationWindow = builder.object("window").expect("window");
    let split_view: OverlaySplitView = builder.object("split_view").expect("split_view");
    let sidebar_list: ListBox = builder.object("sidebar_list").expect("sidebar_list");
    let sidebar_toggle: ToggleButton = builder.object("sidebar_toggle").expect("sidebar_toggle");
    let window_title: WindowTitle = builder.object("window_title").expect("window_title");
    let status_page: StatusPage = builder.object("status_page").expect("status_page");
    let toast_overlay: ToastOverlay = builder.object("toast_overlay").expect("toast_overlay");
    let button: Button = builder.object("button").expect("button");

    window.set_application(Some(app));

    // ── Sync sidebar toggle ↔ split-view visibility (bidirectional) ───────────
    split_view
        .bind_property("show-sidebar", &sidebar_toggle, "active")
        .bidirectional()
        .sync_create()
        .build();

    // NOTE: The Adw.Breakpoint (max-width: 600sp → collapsed: true) is declared
    // directly in window.blp — Blueprint generates the correct XML for it, so
    // no manual Breakpoint code is needed here.

    // ── Button click → toast ─────────────────────────────────────────────────
    {
        let toast_overlay = toast_overlay.clone();
        let window_title = window_title.clone();
        button.connect_clicked(move |_| {
            let page = window_title.title();
            println!("Button clicked on the {page} page!");
            toast_overlay.add_toast(Toast::new(&format!("Button clicked on {page}")));
        });
    }

    // ── Sidebar row selection ─────────────────────────────────────────────────
    {
        let split_view = split_view.clone();
        sidebar_list.connect_row_selected(move |_, row| {
            let Some(row) = row else { return };
            let (title, icon) = PAGES[row.index() as usize];
            println!("Switched to {title}");
            window_title.set_title(title);
            status_page.set_title(title);
            status_page.set_icon_name(Some(icon));

            // On narrow windows the sidebar overlays the content, so hide it after picking
            if split_view.is_collapsed() {
                split_view.set_show_sidebar(false);
            }
        });
    }

    // Select the first row on startup
    sidebar_list.select_row(sidebar_list.row_at_index(0).as_ref());

    window.present();
}
